"""Build the HTML Design example without changing the supplied editor."""
from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "demos"

def photo(name, el, alt, cls="photo"):
    encoded = base64.b64encode((OUT / "assets" / f"{name}.jpg").read_bytes()).decode()
    return f'<img data-el="{el}" class="{cls}" src="data:image/jpeg;base64,{encoded}" width="1400" height="933" alt="{alt}">'

def header(n, label):
    return f'<header class="head"><span data-el="p{n}-series">THE PLAY ARCHIVE</span><span data-el="p{n}-chapter">{label}</span></header>'

def footer(n, label):
    return f'<footer class="foot"><span data-el="p{n}-footer">玩具简史 / {label}</span><span data-el="p{n}-number">{n:02d} / 08</span></footer>'

def page(n, title, content, cls="", label=""):
    return f'<section data-artboard="p{n}" data-title="{title}" data-mode="flow" class="page {cls}" aria-label="第 {n} 页：{title}">{header(n,label)}{content}{footer(n,title)}</section>'

css = '''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--workspace);color:var(--text);font-family:var(--font);-webkit-font-smoothing:antialiased}
[data-stage]{display:flex;flex-direction:column;align-items:center;gap:36px;padding:48px 24px;width:max-content;min-width:100%}
[data-artboard]{position:relative;width:1280px;height:720px;overflow:hidden;background:var(--bg);padding:44px 56px 30px;flex-shrink:0;box-shadow:var(--shadow);scroll-margin-top:24px}
.page{display:flex;flex-direction:column}.head,.foot{display:flex;justify-content:space-between;align-items:center;font-size:13px;line-height:20px;letter-spacing:1.5px}.head{padding-bottom:17px;border-bottom:1px solid var(--line)}.foot{padding-top:16px;border-top:1px solid var(--line);font-size:12px;letter-spacing:1px}.content{flex:1;min-height:0;padding:32px 0}.head span:first-child{font-weight:800;letter-spacing:3px}
h1,h2,h3,p,figure{margin:0}h1,h2,h3{font-weight:800;letter-spacing:-2px}h2{font-size:55px;line-height:1.16}h3{font-size:25px;line-height:1.4;letter-spacing:-.5px}p{font-size:21px;line-height:1.65}.eyebrow{font-size:13px;font-weight:700;letter-spacing:3px;line-height:1.5}.mono{font-family:var(--mono);font-weight:400}.muted{color:var(--muted)}.source{font-size:12px;line-height:1.6;color:var(--muted)}.accent{color:var(--primary)}
.cover{background:var(--red);color:var(--cream);--line:var(--light-line)}.cover .content{display:grid;grid-template-columns:400px 1fr;gap:40px;align-items:center}.cover-copy{display:flex;flex-direction:column;align-items:flex-start;gap:20px}.cover h1{font-size:111px;line-height:1.03;letter-spacing:-7px}.cover h1 span{display:block}.cover .intro{font-size:20px;line-height:1.6;max-width:360px}.photo{display:block;width:100%;height:100%;object-fit:cover;border-radius:var(--radius)}.cover-figure{height:449px;display:flex;flex-direction:column;gap:12px}.cover-figure img{height:421px;flex-shrink:0}.caption{font-size:12px;line-height:16px;letter-spacing:.4px}
.ancient .content{display:grid;grid-template-columns:1.04fr 1fr;gap:76px;align-items:center}.ancient-copy{display:flex;flex-direction:column;gap:27px}.artifact{border-left:1px solid var(--line);padding-left:48px;display:flex;flex-direction:column;gap:28px}.artifact .date{font-family:var(--mono);font-size:54px;line-height:1.1;letter-spacing:-3px}.artifact .small-label{font-size:15px;line-height:1.6}.material{display:flex;gap:24px;font-size:17px;padding-top:18px;border-top:1px solid var(--line)}
.feature .content{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}.feature-copy{display:flex;flex-direction:column;align-items:flex-start;gap:24px}.year{font-size:67px;line-height:1;letter-spacing:-5px;color:var(--primary);font-family:var(--mono)}.feature h2{font-size:52px}.feature .body{font-size:21px;line-height:1.65}.feature-figure{display:flex;flex-direction:column;gap:11px;height:450px}.feature-figure img{height:422px;flex-shrink:0}.bear{background:var(--rose)}.bricks{background:var(--cream)}.digital{background:var(--blue)}.dual-year{display:flex;align-items:baseline;gap:18px}.dual-year .year{font-size:53px;letter-spacing:-3px}.dual-year .between{font-size:18px}.small-block{display:flex;flex-direction:column;gap:6px}.small-block h3{font-size:23px}.small-block p{font-size:18px;line-height:1.55}
.timeline .content{display:flex;flex-direction:column;justify-content:center;gap:40px}.timeline-title{display:flex;justify-content:space-between;align-items:flex-end;gap:44px}.timeline-title p{max-width:390px;font-size:18px}.rail{display:grid;grid-template-columns:1.15fr repeat(4,1fr);gap:24px;border-top:3px solid var(--text);padding-top:23px}.milestone{display:flex;flex-direction:column;gap:15px}.milestone .date{font-size:40px;line-height:1.2;font-family:var(--mono);letter-spacing:-2px}.milestone h3{font-size:23px}.milestone p{font-size:18px;line-height:1.6}.milestone .type{font-size:13px;color:var(--primary);letter-spacing:2px}.note{font-size:14px;line-height:1.5;color:var(--muted)}
.closing{background:var(--red);color:var(--cream);--line:var(--light-line);--muted:var(--light-muted)}.closing .content{display:flex;flex-direction:column;justify-content:center;align-items:flex-start;gap:32px}.closing h2{font-size:78px;line-height:1.2;letter-spacing:-4px}.closing .question{font-size:25px;line-height:1.65}.closing .closing-kicker{font-size:15px;letter-spacing:5px}.closing .afterword{font-size:17px;max-width:740px;line-height:1.7;color:var(--light-muted)}
.sources .content{padding-top:26px;display:flex;flex-direction:column;gap:22px}.sources h2{font-size:40px}.source-list{display:grid;grid-template-columns:1fr 1fr;column-gap:56px;row-gap:22px}.source-item{display:flex;flex-direction:column;gap:5px;padding-bottom:15px;border-bottom:1px solid var(--line)}.source-item .tag{font-size:12px;letter-spacing:2px;color:var(--primary)}.source-item h3{font-size:20px;line-height:1.4;letter-spacing:0}.source-item p{font-size:15px;line-height:1.5}.source-item a{color:var(--text);font-size:13px;text-underline-offset:4px}.source-notes{font-size:14px;line-height:1.7;color:var(--muted);max-width:1040px}
@media print{@page{size:1280px 720px;margin:0}html[data-editor-nav]{padding-left:0!important}body{background:var(--bg);print-color-adjust:exact;-webkit-print-color-adjust:exact}[data-stage]{display:block;padding:0;min-width:0;width:auto}[data-artboard]{box-shadow:none;margin:0;break-after:page;break-inside:avoid}[data-artboard]:last-child{break-after:auto}[data-editor-ui]{display:none}}
'''

pages=[]
pages.append(page(1,"玩具简史",f'''<div class="content"><div class="cover-copy"><p data-el="p1-kicker" class="eyebrow">A LITTLE HISTORY OF TOYS</p><h1 data-el="p1-title">玩具<br>简史<span></span></h1><p data-el="p1-subtitle" class="intro">把一个时代的好奇心，<br>放进小小的玩具里。</p><p data-el="p1-meta" class="eyebrow">古代世界 · 20 世纪末</p></div><figure class="cover-figure">{photo("cover","p1-hero","木马、陀螺、泰迪熊、积木与掌机的静物组合")}<figcaption data-el="p1-caption" class="caption">童年的物件，也是时代的切片。图为 AI 示意。</figcaption></figure></div>''',"cover","收藏童年的好奇心"))
pages.append(page(2,"古代的带轮木马",'''<div class="content"><div class="ancient-copy"><p data-el="p2-kicker" class="eyebrow accent">01 / 很早以前</p><h2 data-el="p2-title">一匹小木马，<br>已经会出发</h2><p data-el="p2-intro">给熟悉的动物装上轮子，<br>一件日常物品就变成了游戏。</p><p data-el="p2-thought" class="source">这类玩具把真实生活缩小，让孩子用动作和想象编故事。</p></div><div data-el="p2-artifact" class="artifact"><p data-el="p2-period" class="eyebrow">罗马时期的埃及</p><p data-el="p2-date" class="date">30 BCE<br>– 395 CE</p><h3 data-el="p2-object">带轮木制玩具马</h3><p data-el="p2-description">布里斯托博物馆的藏品 H1794 有木制轮子，马嘴处留有穿绳孔，可以牵引。</p><div class="material"><span data-el="p2-material">木头</span><span data-el="p2-wheel">轮子</span><span data-el="p2-string">一根绳子</span></div><p data-el="p2-source" class="source">年代为馆藏标注范围，并非玩具的起源日期。[1]</p></div></div>''',"ancient","日常生活的缩影"))
pages.append(page(3,"泰迪熊与陪伴",f'''<div class="content"><figure class="feature-figure">{photo("bear","p3-image","红陶色背景上的复古风格泰迪熊")}<figcaption data-el="p3-caption" class="caption">柔软的触感，让玩具成为可以拥抱的伙伴。AI 示意。</figcaption></figure><div class="feature-copy"><p data-el="p3-kicker" class="eyebrow">02 / 陪伴</p><p data-el="p3-year" class="year">1902</p><h2 data-el="p3-title">一只熊，<br>有了自己的名字</h2><p data-el="p3-body" class="body">罗斯福的一次狩猎故事经漫画传播，启发了以“Teddy”命名的玩具熊。</p><p data-el="p3-takeaway" class="body">孩子给它名字、和它说话，也带着它入睡。玩具承载了陪伴的意义。</p><p data-el="p3-source" class="source">1902 年是命名故事的重要节点，并非所有玩具熊的起点。[2]</p></div></div>''',"feature bear","可以拥抱的伙伴"))
pages.append(page(4,"积木与创造",f'''<div class="content"><div class="feature-copy"><p data-el="p4-kicker" class="eyebrow">03 / 创造</p><p data-el="p4-year" class="year">1958</p><h2 data-el="p4-title">小小积木，<br>可以一再重来</h2><p data-el="p4-body" class="body">乐高在这一年提交积木连接结构的专利申请，凸点与底部管柱让拼接更稳固。</p><p data-el="p4-takeaway" class="body">同一批零件，可以搭房子，也可以拆开重建。玩法随着想象继续生长。</p><p data-el="p4-source" class="source">专利申请日：1958 年 1 月 28 日。此前年代已有乐高塑料积木。[3]</p></div><figure class="feature-figure">{photo("bricks","p4-image","红黄蓝积木搭成的拱形结构")}<figcaption data-el="p4-caption" class="caption">连接结构提供规则，孩子决定最后的形状。AI 示意。</figcaption></figure></div>''',"feature bricks","把答案留给想象"))
pages.append(page(5,"口袋里的电子玩具",f'''<div class="content"><figure class="feature-figure">{photo("digital","p5-image","灰色复古掌机与黄色蛋形电子宠物")}<figcaption data-el="p5-caption" class="caption">一块小屏幕，让反馈和陪伴随身而行。AI 示意。</figcaption></figure><div class="feature-copy"><p data-el="p5-kicker" class="eyebrow">04 / 互动</p><div class="dual-year"><p data-el="p5-year1" class="year">1989</p><span data-el="p5-year-divider" class="between">/</span><p data-el="p5-year2" class="year">1996</p></div><h2 data-el="p5-title">游戏世界，<br>装进了口袋</h2><div data-el="p5-gameboy" class="small-block"><h3 data-el="p5-gameboy-title">Game Boy：随身游戏</h3><p data-el="p5-gameboy-body">1989 年在日本推出。通过更换卡带，一台掌机可以带来不同的游戏。[4]</p></div><div data-el="p5-tamagotchi" class="small-block"><h3 data-el="p5-tamagotchi-title">拓麻歌子：照顾虚拟生命</h3><p data-el="p5-tamagotchi-body">1996 年 11 月 23 日在日本上市，把喂食与照料变成日常互动。[5]</p></div></div></div>''',"feature digital","会回应的游戏世界"))

items=[("roman","古代","带轮木马","模仿","把身边的动物，<br>变成可牵引的故事。"),("bear","1902","泰迪熊","陪伴","柔软的伙伴，<br>拥有了名字与记忆。"),("brick","1958","现代乐高积木","创造","可重复拼搭的零件，<br>留出自由发挥的空间。"),("gb","1989","Game Boy","随身游戏","更换卡带，<br>进入新的游戏世界。"),("tama","1996","拓麻歌子","持续互动","一只虚拟宠物，<br>需要每天照顾。")]
rail="".join(f'<div data-el="p6-{key}" class="milestone"><p data-el="p6-{key}-date" class="date">{date}</p><p data-el="p6-{key}-type" class="type">{kind}</p><h3 data-el="p6-{key}-title">{title}</h3><p data-el="p6-{key}-body">{body}</p></div>' for key,date,title,kind,body in items)
pages.append(page(6,"五个节点，一条时间线",f'''<div class="content"><div class="timeline-title"><h2 data-el="p6-title">玩法不断增加，<br>旧玩具仍有位置</h2><p data-el="p6-intro" class="muted">材料和技术带来了新的体验。<br>木马、毛绒玩具与积木，<br>也继续出现在今天的童年里。</p></div><div class="rail">{rail}</div><p data-el="p6-note" class="note">选取五个代表性节点，不是完整编年史。日期分别指馆藏时期、命名故事、专利申请或产品上市。[1–5]</p></div>''',"timeline","回看玩具的变化"))
pages.append(page(7,"你的童年收藏",'''<div class="content"><p data-el="p7-kicker" class="closing-kicker">留一点时间，想起小时候</p><h2 data-el="p7-title">你最想找回的，<br>是哪一件玩具？</h2><p data-el="p7-question" class="question">它是什么样子？你当时和谁一起玩？</p><p data-el="p7-afterword" class="afterword">玩具会记录技术的变化，也会留下个人的故事。<br>也许我们记得最清楚的，是那个一起玩的下午。</p></div>''',"closing","给童年留一个位置"))

sources=[("1","古代带轮木马","Bristol Museums / Toy, H1794","https://museums.bristol.gov.uk/details.php?irn=83660","馆藏材料、结构与罗马时期的年代范围。"),("2","泰迪熊的命名故事","Smithsonian / Teddy Bear","https://americanhistory.si.edu/press/fact-sheets/teddy-bear","1902 年的罗斯福狩猎事件与漫画传播。"),("3","乐高积木连接结构","LEGO / The stud and tube principle","https://www.lego.com/en-nz/history/articles/d-the-stud-and-tube-principle","1958 年 1 月 28 日提交专利申请。"),("4","Game Boy 的上市","Nintendo / Game Boy","https://www.nintendo.com/en-gb/Hardware/Nintendo-History/Game-Boy/Game-Boy-627031.html","1989 年在日本推出，以及卡带式游戏。"),("5","拓麻歌子的上市","Bandai / 20th Anniversary press release","https://www.bandainamco.co.jp/cgi-bin/releases/index.cgi/file/view/5986?entry_id=5435","1996 年 11 月 23 日在日本上市。")]
listing="".join(f'<div data-el="p8-source{n}" class="source-item"><p data-el="p8-source{n}-tag" class="tag">参考 {n}</p><h3 data-el="p8-source{n}-title">{title}</h3><p data-el="p8-source{n}-detail">{desc}</p><a data-el="p8-source{n}-link" href="{url}" target="_blank" rel="noreferrer">{label}</a></div>' for n,title,label,url,desc in sources)
listing+='''<div data-el="p8-illustrations" class="source-item"><p data-el="p8-illustrations-tag" class="tag">图像说明</p><h3 data-el="p8-illustrations-title">四幅 AI 生成静物插图</h3><p data-el="p8-illustrations-detail">为叙事绘制的现代示意，非馆藏实物照片。<br>不以图像细节作为历史考证依据。</p></div>'''
pages.append(page(8,"资料与图像说明",f'''<div class="content"><h2 data-el="p8-title">资料与图像说明</h2><div class="source-list">{listing}</div><p data-el="p8-note" class="source-notes">本演示以少量代表性玩具串联历史，未覆盖所有地区与品类。“模仿、陪伴、创造、互动”为本稿的叙事归纳，<br>并非互斥的历史阶段。资料核对：2026 年 10 月。部分来源站点可能暂时维护，可按机构及标题检索。</p></div>''',"sources","继续探索"))

design='''
:root{--primary:#b6462e;--text:#262820;--muted:#636454;--bg:#f7f3e9;--font:"Avenir Next","PingFang SC","Microsoft YaHei",system-ui,sans-serif;--mono:"Helvetica Neue",Arial,sans-serif;--radius:2px;--gap:24px;--workspace:#deded8;--yellow:#f2ce66;--cream:#f7f3e9;--rose:#f0dfd6;--blue:#d9e7ec;--red:#a23c2a;--line:rgba(38,40,32,.21);--light-line:rgba(247,243,233,.35);--light-muted:#efc9b7;--shadow:0 8px 40px rgba(38,40,32,.09)}
'''
editor=(ROOT / "html-design" / "editor.js").read_text()
html='<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>玩具简史 · The Play Archive</title>\n<style data-design>'+design+'</style>\n<style>'+css+'</style>\n</head>\n<body>\n<main data-stage>\n'+"\n".join(pages)+'\n</main>\n<script data-editor>'+editor+'</script>\n</body>\n</html>\n'
(OUT / "toy-history.html").write_text(html)
print(f'Built {len(pages)} artboards; {len(html.encode()):,} bytes')
